import { useNavigate } from "react-router-dom";
import { useEffect, useState } from "react";
import logo from "./—Pngtree—summer coast vacation logo_5462462.png";
import { auth } from "../firebase";
import { onAuthStateChanged, signOut } from "firebase/auth";

// Main Navbar Component
function Navbar({
  search,
  setSearch,
  color,
  setColor,
  showSearchBar,
  component,
  setShowSearchBar,
  loggedIn,
  setLoggedIn,
}) {
  const [isOpen, setIsOpen] = useState(false);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);

  function toggleDropdown() {
    console.log(isDropdownOpen);
    
    setIsDropdownOpen((prev) => !prev);
  }

  const toggleNavbar = () => {
    setIsOpen((prev) => !prev);
  };

  const navigate = useNavigate();

  // Function to handle changes in the search input
  function handleChange(e) {
    setSearch(e.target.value);
  }

  // Function to handle the search submission
  function handleSearch(e) {
    e.preventDefault();
    const packagesElement = document.querySelector("#packages");
    if (packagesElement) {
      setTimeout(() => {
        packagesElement.scrollIntoView({ behavior: "smooth" });
      }, 100);
    } else {
      console.error("Element with ID 'packages' not found.");
    }
  }

  // Function to handle user logout
  function handleLogout() {
    signOut(auth)
      .then(() => {
        setLoggedIn(false);
        navigate("/getway-travels");
      })
      .catch((error) => {
        console.log(error);
      });
  }

  // Hook to setup and clean up the navbar color during scrolling
  useEffect(() => {
    const handleScroll = () => {
      const lineargradient =
        window.scrollY > 600
          ? "radial-gradient(circle at 24.1% 68.8%, rgb(50, 50, 50,0.97) 0%, rgb(0, 0, 0,0.97) 99.4%)"
          : "";
      setColor((prev) => ({ ...prev, lineargradient: lineargradient }));
    };

    if (component === "landing") {
      window.addEventListener("scroll", handleScroll);
    } else {
      setShowSearchBar(false);
      if (component == "contactUs" || component == "feedbackForm") {
        setColor((prev) => ({
          ...prev,
          lineargradient:
            "linear-gradient(112.1deg, rgb(32, 38, 57) 11.4%, rgb(63, 76, 119) 70.2%)",
          text: "white",
        }));
      } else {
        setColor((prev) => ({
          ...prev,
          text: "white",
          lineargradient:
            "radial-gradient(circle at 24.1% 68.8%, rgb(50, 50, 50,0.65) 0%, rgb(0, 0, 0,0.65) 99.4%)",
        }));
      }
    }
    return () => window.removeEventListener("scroll", handleScroll);
  }, [component]);

  // Authentication state observer to manage user login status
  useEffect(() => {
    onAuthStateChanged(auth, (user) => {
      if (user) {
        setLoggedIn(true);
      } else {
        setLoggedIn(false);
      }
    });
  }, []);

  return (
    <nav
      className="navbar navbar-expand-lg navbar-light"
      style={{
        position: "fixed",
        width: "100%",
        zIndex: 10,
        backgroundColor: color.nav,
        backgroundImage: color.lineargradient,
        color: "white",
        fontSize: "larger",
        height: "10vh",
      }}
    >
      <div className="container-fluid  ">
        <div
          className="navbar-brand ms-4"
          onClick={() => {
            navigate("/getway-travels");
          }}
          style={{
            color: color.text,
            fontSize: "35px",
            fontWeight: "bold",
            cursor: "pointer",
          }}
        >
          <img src={logo} alt="logo" style={{ width: "60px" }} /> Getway Travels
        </div>
        <button
          className="navbar-toggler"
          type="button"
          onClick={toggleNavbar}
          aria-expanded={isOpen}
        >
          <span className="navbar-toggler-icon"></span>
        </button>

        <div
          className={`navbar-collapse bg-gray-900/85 sm:bg-gray-900/0 p-2 rounded-md  ${
            isOpen ? "block" : "hidden"
          }`}
          id="navbarSupportedContent"
        >
          <ul className="navbar-nav ms-auto mb-2 mb-lg-0">
            <li className="nav-item">
              <span
                className="nav-link active"
                aria-current="page"
                style={{ color: color.text, cursor: "pointer" }}
                onClick={() => navigate("/getway-travels")}
              >
                Home
              </span>
            </li>
            <li className="nav-item">
              <span
                className="nav-link"
                style={{ color: color.text, cursor: "pointer" }}
                onClick={() => navigate("/getway-travels/wishlist")}
              >
                WishList
              </span>
            </li>
            <li className="nav-item">
              <span
                className="nav-link"
                style={{ color: color.text, cursor: "pointer" }}
                onClick={() => navigate("/getway-travels/contactUs")}
              >
                 Contact Us
              </span>
            </li>
            <li className="nav-item">
              <span
                className="nav-link"
                style={{ color: color.text, cursor: "pointer" }}
                onClick={() => navigate("/getway-travels/feedbackForm")}
              >
                 Feedback
              </span>
            </li>
           
            {!loggedIn && (
              <li className="nav-item">
                <span
                  className="nav-link"
                  onClick={() => {
                    navigate("/getway-travels/login");
                  }}
                  style={{ color: color.text, cursor: "pointer" }}
                >
                  Login
                </span>
              </li>
            )}
            {!loggedIn && (
              <li className="nav-item">
                <span
                  className="nav-link"
                  style={{ color: color.text, cursor: "pointer" }}
                  onClick={() => navigate("/getway-travels/signUp")}
                >
                  SignUp
                </span>
              </li>
            )}
            {loggedIn && (
              <li className="nav-item">
                <span
                  className="nav-link"
                  style={{ color: color.text, cursor: "pointer" }}
                  onClick={handleLogout}
                >
                  Logout
                </span>
              </li>
            )}
          </ul>

          {showSearchBar && (
            <form className="d-flex" onSubmit={handleSearch}>
              <input
                className="form-control me-2"
                type="search"
                placeholder="Search"
                aria-label="Search"
                value={search}
                onChange={handleChange}
                style={{
                  color: color.text,
                  backgroundColor: "rgba(255, 255, 255, 0.1)",
                  fontSize: "14px",
                  padding: "8px 5px",
                }}
              />

              <button
                type="submit"
                style={{
                  color: color.text,
                  fontSize: "14px",
                  padding: "8px 5px",
                }}
              >
                Search
              </button>
            </form>
          )}
        </div>
      </div>
    </nav>
  );
}
export default Navbar;
